import React, { Component } from "react";
import "./Signup.css";
import FormJson from "./formid";

export default class Signup extends Component {
    render() {
        const signData = FormJson.find(item => item.formId === 3);
        const contentSign1 = signData.content[0].leftside;
        const contentSign2 = signData.content[1].r;


        return (
            <div className="content-container">
                <div className="formbox">
                    <div className="button-box">
                        <div id="btn"></div>
                        <button type="button" className="toggle-btn">Log In</button>
                        <button type="button" className="toggle-btn">Sign Up</button> 
                    </div>
                    <div className="social-icons">
                        <img src="fb.png" alt="Facebook" />
                        <img src="gb.png" alt="Google" />
                    </div>

                    <form className="input-group">
                     <div className="input-left">
                        {contentSign1.map((item) =>(
                       <>
                    <input 
                    type={item.type} 
                    className={item.className} 
                    placeholder={item.placeholder} 
                    required />
                    </>
                     ))}
                        </div>

                    <div className="input-right">
                    {contentSign2.map((item) =>(
                       <>
                    <input 
                    type={item.type} 
                    className={item.className} 
                    placeholder={item.placeholder} 
                    required />
                    </>
                     ))}
                        </div>

                    </form>
                    <button type="submit" className="submit-btn">Sign Up</button>

                </div>
            </div>
        );
    }
}
